"""Installer AI setup UI: metadata drafts and direct-to-vault credentials."""
import html
import json
import ai_provisioning as ai


def render():
    catalog = json.dumps([{**row, 'id': ident} for ident, row in ai.CATALOG.items()]).replace('<', '\\u003c')
    return ('''<!doctype html><html><head><meta charset="utf-8"><title>Installer AI setup</title>
<style>body{font:16px system-ui;background:#101a28;color:#eef4fa;max-width:1000px;margin:32px auto;padding:20px}fieldset{margin:18px 0;padding:18px;border:1px solid #526579}label{display:block;margin:10px 0}input,select,textarea,button{font:inherit}textarea{display:block;width:95%;min-height:100px}small{display:block;color:#bac8da}button,a{color:#63d7c1}button{background:#23384e;padding:10px}input[type=checkbox]{margin-right:10px}</style></head><body>
<h1>AI setup for this build</h1><p><a href="/install-plan">Back to installer</a> · <a href="/vault">USER_ADMIN vault</a> · <a href="/ai-setup">Provider status</a></p>
<p>Prepare before boot for a new build, update or rebuild. Secrets and native MCP/auth files go directly into the encrypted USER_ADMIN vault; the plan contains only selections and a profile reference. Unlocking the vault is required on each boot.</p>
<form id="ai-form"><fieldset><legend>Configuration source</legend><label>Setup <select id="ai-mode"><option value="none">Do not configure AI</option><option value="parent">Import selected parent setup</option><option value="custom">Use custom settings</option></select></label>
<label><input id="claude-history" type="checkbox"> Import Claude Code conversations, prompt history, checkpoints and plans into private APPDATA_ADMIN data</label><p>This also prepares an editable build checkout. Use baseline-maintain inside the build to resume a session and work on fixes.</p><p id="parent-status" role="status"></p></fieldset>
<fieldset><legend>Providers and clients</legend><div id="ai-providers"></div></fieldset>
<fieldset><legend>Permitted places</legend><p>Grant only to places that should receive this setup. Future matching guests receive it when they start and the vault is unlocked.</p>
<div id="ai-targets"></div></fieldset>
<fieldset id="custom-fields"><legend>Custom provider settings</legend><label>Client <select id="custom-provider"></select></label>
<label>Credential variable<select id="custom-key-name"><option>OPENAI_API_KEY</option><option>CLAUDE_CODE_OAUTH_TOKEN</option><option>ANTHROPIC_API_KEY</option><option>GEMINI_API_KEY</option><option>GOOGLE_API_KEY</option><option>OPENROUTER_API_KEY</option></select></label><label>API key / setup token<input id="custom-api-key" type="password" autocomplete="off"></label><label>Service address variable<select id="custom-endpoint-name"><option>OPENAI_BASE_URL</option><option>OLLAMA_HOST</option></select></label><label>Service address (optional)<input id="custom-endpoint" type="url" placeholder="http://parent-host:11434"></label><p>Additional settings: enter environment names/values as JSON. These values are submitted directly to the vault, never saved in the draft. For native auth files use the parent's importer, or supply their base64 bytes in the complete custom profile.</p>
<label>Provider environment (JSON object)<textarea id="custom-env" autocomplete="off" spellcheck="false" placeholder='{"OPENAI_API_KEY":"enter privately here"}'></textarea></label>
<button id="add-custom" type="button">Keep settings for this client in this form</button>
<label>Native MCP documents by client (JSON object)<textarea id="custom-mcp" autocomplete="off" spellcheck="false" placeholder='{"codex":"[mcp_servers.example]\\nurl = \\"https://example.invalid/mcp\\""}'></textarea></label>
<details><summary>Complete custom profile override (optional)</summary><textarea id="custom-profile" autocomplete="off" spellcheck="false" placeholder='{"providers":{},"mcp":{}}'></textarea></details></fieldset>
<p>If the vault has not been set up, choose its passphrase on the vault page first. Enter credentials only into this application, never into agent chat.</p>
<button type="submit" id="ai-save">Save encrypted setup and installer choice</button><p id="ai-status" role="status" aria-live="polite"></p></form>
<fieldset><legend>Use the prepared setup</legend><p>After unlocking the vault, activate host tools or deliver to a running VM, container, Kasm server or workspace. Programs launch with <code>baseline-ai-run PROVIDER -- PROGRAM</code>. This selects that provider's API settings and native auth/MCP files.</p>
<label>Target<input id="ai-delivery-target" value="baseline" list="delivery-targets"><datalist id="delivery-targets"><option value="substrate"><option value="baseline"><option value="kasm"></datalist></label><label>Guest account (blank: detect the unique managed owner)<input id="ai-delivery-account" autocomplete="off"></label>
<button id="ai-deliver" type="button">Activate / deliver</button><p id="delivery-status" role="status"></p></fieldset>
<script>const catalog=''' + catalog + ''';
const targets=[['substrate','Proxmox host tools'],['baseline','BaselineOS tools'],['vm:*','Managed VMs'],['ct:*','Managed containers'],['kasm:*','Kasm server and workspaces']];let revision=0,custom={};
const status=document.getElementById('ai-status');
async function call(url,body){const r=await fetch(url,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const j=await r.json();if(!r.ok||j.ok===false)throw Error(j.message||'Request failed');return j;}
for(const c of catalog){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.value=c.id;input.name='provider';label.append(input,document.createTextNode(c.name));if(c.notice){const note=document.createElement('small');note.textContent=c.notice;label.append(note);}document.getElementById('ai-providers').append(label);document.getElementById('custom-provider').add(new Option(c.name,c.id));}
for(const [id,name] of targets){const l=document.createElement('label'),i=document.createElement('input');i.type='checkbox';i.value=id;i.name='target';l.append(i,document.createTextNode(name));document.getElementById('ai-targets').append(l);}
document.getElementById('add-custom').onclick=()=>{try{const id=document.getElementById('custom-provider').value;const env=JSON.parse(document.getElementById('custom-env').value||'{}');if(document.getElementById('custom-api-key').value)env[document.getElementById('custom-key-name').value]=document.getElementById('custom-api-key').value;if(document.getElementById('custom-endpoint').value)env[document.getElementById('custom-endpoint-name').value]=document.getElementById('custom-endpoint').value;custom[id]={env,files:{}};document.getElementById('custom-api-key').value='';document.getElementById('custom-endpoint').value='';document.querySelector('[name=provider][value="'+id+'"]').checked=true;document.getElementById('custom-env').value='';status.textContent='Client settings held in this form until encrypted save.';}catch(e){status.textContent='Invalid environment JSON';}};
document.getElementById('custom-provider').onchange=()=>{const id=document.getElementById('custom-provider').value;const name={codex:'OPENAI_API_KEY',openai:'OPENAI_API_KEY','claude-code':'CLAUDE_CODE_OAUTH_TOKEN',gemini:'GEMINI_API_KEY',openrouter:'OPENROUTER_API_KEY'}[id];if(name)document.getElementById('custom-key-name').value=name;document.getElementById('custom-endpoint-name').value=id==='ollama'?'OLLAMA_HOST':'OPENAI_BASE_URL';};
document.getElementById('ai-form').onsubmit=async e=>{e.preventDefault();try{const selection={mode:document.getElementById('ai-mode').value,providers:[...document.querySelectorAll('[name=provider]:checked')].map(n=>n.value),targets:[...document.querySelectorAll('[name=target]:checked')].map(n=>n.value),profile:'AI_SETUP_DEFAULT',claude_history:document.getElementById('claude-history').checked};const body={selection,revision};if(selection.mode==='custom'){body.profile=document.getElementById('custom-profile').value?JSON.parse(document.getElementById('custom-profile').value):{providers:custom,mcp:JSON.parse(document.getElementById('custom-mcp').value||'{}')};}const j=await call('/ai-setup/installer-profile',body);revision=j.revision;custom={};for(const id of ['custom-api-key','custom-endpoint','custom-env','custom-mcp','custom-profile'])document.getElementById(id).value='';status.textContent=j.message;}catch(error){status.textContent=error.message;}};
document.getElementById('ai-deliver').onclick=async()=>{try{const j=await call('/ai-setup/activate',{target:document.getElementById('ai-delivery-target').value,account:document.getElementById('ai-delivery-account').value});document.getElementById('delivery-status').textContent=j.message;}catch(e){document.getElementById('delivery-status').textContent=e.message;}};
call('/ai-setup/installer-state').then(j=>{revision=j.revision;document.getElementById('ai-mode').value=j.selection.mode;document.getElementById('claude-history').checked=j.selection.claude_history===true;for(const p of j.selection.providers)document.querySelector('[name=provider][value="'+p+'"]').checked=true;for(const t of j.selection.targets)document.querySelector('[name=target][value="'+t+'"]').checked=true;document.getElementById('parent-status').textContent=j.parent.map(p=>p.name+': '+(p.files.length+p.environment.length)+' importable settings/files').join('; ');status.textContent=j.prepared?'Encrypted profile prepared. Saving custom mode again requires entering the replacement settings.':'No prepared profile yet.';}).catch(e=>{status.textContent=e.message;document.getElementById('ai-save').disabled=true;});
</script></body></html>''').encode()
